//! `method_catalogue` — the app-owned method catalogue (TxResBench).
//!
//! A stateless, DB-free module (DEC-9): the catalogue — method facts, marker
//! vocabulary with the 7 board groups, per-method timing/performance aggregates
//! — is embedded at build time from `data/method-catalogue/catalogue.json`
//! (generated by `scripts/method-catalogue/gen_method_catalogue.py`, never read
//! from the benchmark tree at run time — INV-1) and boot-validated by
//! [`catalogue`] (the first-party-data posture: a catalogue we ship that we
//! cannot interpret is a boot refusal, DEC-15). No database, no migration, no
//! socket, no events (the per-method run-progress stream belongs to the
//! execution engine).
//!
//! The module's surfaces are:
//! - the in-process seam [`catalogue`] (PROV-MC-7): [`catalogue::catalogue`],
//!   [`catalogue::method`], [`catalogue::env_for`],
//!   [`catalogue::marker_vocabulary`], plus the matching/estimate engine
//!   functions ([`eligibility`] — the data.py rule port + the eligibility
//!   engine, ITEM-3; [`estimate`] — the time-estimate engine, ITEM-4);
//! - the measured-time calibration [`calibration`] (qa-fixes2 ITEM-6,
//!   R2-3): the estimate engine scales its per-fold bases with THIS app's
//!   own measured durations, loaded by the consumers as a pure snapshot —
//!   the engine itself stays DB-free; the calibration is an input, like the
//!   catalogue;
//! - the typed request/response contract [`types`] (PROV-MC-1..6), which the
//!   five HTTP endpoints (method list, method detail, marker vocabulary,
//!   eligibility, estimate) are layered on in this module's `routes` submodule.

pub mod calibration;
pub mod catalogue;
pub mod eligibility;
pub mod estimate;
pub mod routes;
pub mod types;

use aide::axum::ApiRouter;
use linkme::distributed_slice;

use txresbench_framework::{AppModule, ModuleContext, ModuleEntry, MODULE_ENTRIES};

/// The module instance (no state — the catalogue's `OnceLock` is the only
/// runtime fact, set by `init`).
pub struct MethodCatalogueModule;

impl AppModule for MethodCatalogueModule {
    fn name(&self) -> &'static str {
        "method_catalogue"
    }

    fn description(&self) -> &'static str {
        "App-owned method catalogue: embedded method + marker facts, eligibility matching and time estimates (TxResBench)."
    }

    fn init(&mut self, _ctx: &ModuleContext) -> Result<(), Box<dyn std::error::Error>> {
        // The boot check: parse + validate the embedded catalogue ONCE here. An
        // error is the boxed named refusal (`CatalogueLoadError`) — module init
        // errors abort the boot, so a malformed first-party catalogue is never
        // silently degraded into an empty method list (DEC-15).
        let c = catalogue::ensure_loaded().map_err(|e| {
            Box::<dyn std::error::Error>::from(format!("method catalogue load failed: {e}"))
        })?;
        tracing::info!(
            methods = c.methods.len(),
            markers = c.markers.len(),
            groups = c.groups.len(),
            "method catalogue loaded from the embedded file"
        );
        Ok(())
    }

    fn register_routes(&self, router: ApiRouter) -> ApiRouter {
        // The five endpoints (method list, method detail, marker vocabulary,
        // eligibility, estimate) register here from the module's `routes`
        // submodule; the module ships them under the `/api/methods` prefix with
        // the reused `projects::use` permission (no new permission — DEC-10).
        router.merge(routes::method_catalogue_routes())
    }
}

/// Module registration. Distinct order (47) — see
/// `modules/mod.rs::module_order_is_unique`; 46 is `features`, 60 is `rootfs`.
#[distributed_slice(MODULE_ENTRIES)]
static METHOD_CATALOGUE: ModuleEntry = ModuleEntry {
    name: "method_catalogue",
    order: 47,
    description: "App-owned method catalogue + eligibility/time estimates (TxResBench).",
    constructor: || Box::new(MethodCatalogueModule),
};

// The PROV-MC-8 registration invariant, pinned HERE so the node owns its half
// of the check: `modules/mod.rs::module_order_is_unique` (the framework test)
// is red on a PRE-EXISTING order-4 tie (`health` + `localsession`) at the
// branch base, so the node's own acceptance is asserted locally and the
// framework tie stays an epic-level finding (DRIFT-1).
#[cfg(test)]
mod tests {
    use txresbench_framework::{AppModule, MODULE_ENTRIES};

    use super::METHOD_CATALOGUE;

    /// TEST-MC-20 (node half): `method_catalogue` is registered under
    /// `MODULE_ENTRIES` exactly once, with the declared order 47, and no OTHER
    /// module occupies 47 — `order` uniqueness for THIS node. The framework
    /// test's global tie (health+localsession at 4) is not this node's; it is
    /// recorded in DRIFT-1 as an epic-level finding.
    #[test]
    fn method_catalogue_registers_once_at_unique_order_47() {
        let me: Vec<_> = MODULE_ENTRIES
            .iter()
            .filter(|e| e.name == "method_catalogue")
            .collect();
        assert_eq!(me.len(), 1, "exactly one method_catalogue registration: {me:?}");
        assert_eq!(me[0].order, 47, "the declared integration order");

        let order47: Vec<_> = MODULE_ENTRIES
            .iter()
            .filter(|e| e.order == 47)
            .map(|e| e.name)
            .collect();
        assert_eq!(order47, vec!["method_catalogue"], "no other module at order 47");

        // The module instance builds through the constructor (the boot path's
        // own API — a constructor won't change shape without failing here).
        let built = (me[0].constructor)();
        assert_eq!(built.name(), "method_catalogue");
    }
}
